/* @autogenerated */
package net.civeira.phylax.feature.oauth.userinvitation.infrastructure.driven;

import java.time.OffsetDateTime;
import java.util.Map;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.identity.tenant.domain.TenantRef;
import net.civeira.phylax.feature.notification.outbox.application.usecase.enqueue.EnqueueNotificationCommand;
import net.civeira.phylax.feature.notification.outbox.application.usecase.enqueue.EnqueueNotificationUseCase;
import net.civeira.phylax.feature.notification.outbox.domain.ChannelOptions;
import net.civeira.phylax.feature.oauth.userinvitation.domain.gateway.UserInvitationMailGateway;

/**
 * Sends the invitation email through the notification outbox, template {@code user.invitation}
 * (task 2.2). A failure to enqueue is logged: the administrator can resend the invitation.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class UserInvitationMailAdapter implements UserInvitationMailGateway {

  private final EnqueueNotificationUseCase enqueue;

  @Override
  public void sendInvitation(String toEmail, TenantRef tenant, String acceptUrl,
      String invitedByEmail, OffsetDateTime expiresAt) {
    try {
      enqueue.enqueue(EnqueueNotificationCommand.builder().templateCode("user.invitation")
          .channel(ChannelOptions.MAIL).tenant(tenant).recipient(toEmail)
          .variables(Map.<String, Object>of("invitation", Map.of("url", acceptUrl, "invitedBy",
              invitedByEmail == null ? "" : invitedByEmail, "expiresAt", expiresAt.toString())))
          .urgent(false).build());
    } catch (Exception ex) {
      log.warn("Unable to enqueue the invitation email for {}: {}", toEmail, ex.getMessage());
    }
  }
}
